class Solution_0:
    def stoneGameIX(self, stones: List[int]) -> bool:
        cntOfStones = [0] * 3
        for val in stones:
            cntOfStones[val % 3] += 1

        print('cntOfStones', cntOfStones)

        sumOfInit = sum(cntOfStones)
        memo = {}
        bobLoose = False

        def rec(player, remainder, available):
            nonlocal memo, sumOfInit, bobLoose

            if bobLoose:
                return player == 0

            sumOfAv = sum(available)

            if remainder % 3 == 0 and sumOfAv != sumOfInit:
                if player == 0:
                    bobLoose = True
                return True

            if sumOfAv == 0:
                return player == 1

            _atos = "_".join([str(v) for v in available])
            key = f"{player}_{remainder}_{_atos}"
            if key in memo:
                return memo[key]


            nextWin = True
            for v in range(3):
                c = available[v]
                if c == 0:
                    continue

                _curr = (v + remainder) % 3
                if _curr == 0:
                    continue

                _available = available[:v] + [c - 1] + available[v + 1 :]

                n = rec((player+1)%2, _curr, _available)
                if not n:
                    nextWin = False
                    break

            memo[key] = not nextWin
            if nextWin == False and player == 0:
                bobLoose = True

            return memo[key]

        # r = rec(0, 0, cntOfStones)

        return rec(0, 0, cntOfStones)

class Solution:
    def stoneGameIX(self, stones: List[int]) -> bool:
        cntOfStn = [0] * 3
        for val in stones:
            cntOfStn[val % 3] += 1

        # print('cntOfStones', cntOfStn)

        cntOfStn = [c%100 for c in cntOfStn]


        if cntOfStn[1] == 0 and cntOfStn[2] == 0:
            return False

        memo = {}
        bobLoose = False

        def rec(player, remainder, available):
            nonlocal memo, bobLoose

            if bobLoose:
                return player == 0

            if sum(available) == 0:
                return player == 1

            _av = ''.join([str(c) for c in available])
            key = f'{player}_{remainder}_{_av}'
            if key in memo:
                return memo[key]

            res = False
            if remainder == 2:
                if available[0] > 0:
                    r = rec((player+1)%2, 2, [available[0]-1, available[1], available[2]])
                    if not r:
                        res = True
                if available[2] > 0 and not res:
                    r = rec((player+1)%2, 1, [available[0], available[1], available[2]-1])
                    if not r:
                        res = True

            if remainder == 1:
                if available[0] > 0:
                    r = rec((player+1)%2, 1, [available[0]-1, available[1], available[2]])
                    if not r:
                        res = True
                if available[1] > 0 and not res:
                    r = rec((player+1)%2, 2, [available[0], available[1]-1, available[2]])
                    if not r:
                        res = True

            if player == 0 and res == True:
                bobLoose = True

            memo[key] = res
            return memo[key]

        if cntOfStn[1] > 0:
            r = rec(1, 1, [cntOfStn[0], cntOfStn[1]-1, cntOfStn[2]])
            if not r:
                return True

        if cntOfStn[2] > 0:
            r = rec(1, 2, [cntOfStn[0], cntOfStn[1], cntOfStn[2]-1])
            if not r:
                return True

        return False

class Solution_correct:
    def stoneGameIX(self, stones: List[int]) -> bool:
        cnt = [0, 0, 0]
        for stone in stones:
            cnt[stone % 3] += 1

        # If 0s count is EVEN: Alice wins if both 1s and 2s exist
        if cnt[0] % 2 == 0:
            return cnt[1] > 0 and cnt[2] > 0

        # If 0s count is ODD: Alice wins if difference between 1s and 2s > 2
        return abs(cnt[1] - cnt[2]) > 2


